-- Generated by scripts/build-ai-task-budget-catalog.ts.
-- Install drawing_task_budget and compatible ask-bob/bob-worker first.
begin;
do $task_budget_catalog$
declare texts jsonb:=$task_budget_texts$[
  {
    "key": "bob.frame.outstanding",
    "content": "Outstanding drawing requests (private working state, not verified project truth). Resume the matching request_id after complements; preserve saved work and follow-up Tasks. The budget limits one real owner message/task, including its review and repair loop. Every next owner message starts a fresh full task budget. On a cost-stopped drawing, call design_project_cad with the same request_id at once; do not read requests, budgets or sources first. Replays, worker segments and automatic continuations do not reset or add budget."
  },
  {
    "key": "feedback.bob-budget-stop.resume.eefd1193bc73",
    "content": "This task reached its cost or call limit. Tell the owner the actual cause and finish this reply. Do not read requests, budgets or sources to bypass the stop. The next owner message starts a fresh full task budget with zero spent and zero calls; it does not add to old debt. Continue design_project_cad at once with this same request_id and saved handoff. Reuse the saved draft when sources still match. Same-task retries and automatic continuations never reset or top up the budget."
  },
  {
    "key": "feedback.bob-budget-stop.resume.51aac0199a6c",
    "content": "This task reached the ordinary turn cost or call limit. Tell the owner the actual cause and finish this reply. The next owner message starts a fresh full budget and can continue the same request_id from saved work. Do not retry or top up within this task."
  }
]$task_budget_texts$::jsonb;
 tool jsonb:=$task_budget_tool${
  "request_id_description": "Copy the saved drawing request ID to resume after complements. Null only for a new request. With an ID, pass handoff:null and requirement_changes:[] to reuse ALL saved requirements. When the owner writes again about a request that stopped at its cost or call limit, call this immediately with that ID; the owner's new message starts a fresh task budget, which the server resets. Do not re-read requests, budgets or sources first.",
  "additional_description": "The guard bounds one real owner message/task, including every drawing request and review/repair in that task. A new owner message starts a fresh $3 / 24-call CAD period; same-task retries, new request IDs and automatic continuations cannot refill it. Loading the saved request opens the new period server-side; preserve the same request ID, requirements and current draft. Never add budget automatically."
}$task_budget_tool$::jsonb;
 patch jsonb; prior shared.ai_prompt_versions; next_version integer; version_uuid uuid; definition jsonb; activation jsonb:='{}';
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 for patch in select value from jsonb_array_elements(texts) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
   where p.app='bob' and p.prompt_key=patch->>'key' for update of p;
  if not found then raise exception 'task_budget_instruction_missing';end if;
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,
    (prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','owner-task-budget'),patch->>'content',prior.definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(patch->>'key',version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id
  where p.app='bob' and p.prompt_key='tools.design_project_cad' for update of p;
 if not found then raise exception 'task_budget_tool_missing';end if;
 definition:=jsonb_set(prior.definition,'{parameters,properties,request_id,description}',tool->'request_id_description');
 definition:=jsonb_set(definition,'{additional_description}',to_jsonb(coalesce(prior.definition->>'additional_description','')||E'\n\n'||(tool->>'additional_description')));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,
   (prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','owner-task-budget'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('tools.design_project_cad',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $task_budget_catalog$;
commit;
